import os
import hashlib
import hmac
from flask import Flask, request, jsonify, session
from functools import wraps
import sqlite3
import pickle
import base64
import zlib

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

class UserPreferences:
    def __init__(self, theme='light', locale='en', notifications=True):
        self.theme = theme
        self.locale = locale
        self.notifications = notifications

@app.route('/api/preferences', methods=['GET'])
@require_auth
def get_preferences():
    db = get_db()
    row = db.execute('SELECT prefs_blob FROM user_prefs WHERE user_id = ?', 
                     (session['user_id'],)).fetchone()
    if row and row['prefs_blob']:
        # Decompress and deserialize stored preferences
        try:
            raw = base64.b64decode(row['prefs_blob'])
            decompressed = zlib.decompress(raw)
            prefs = pickle.loads(decompressed)
            return jsonify({
                'theme': prefs.theme,
                'locale': prefs.locale,
                'notifications': prefs.notifications
            })
        except Exception as e:
            app.logger.warning(f'Failed to load prefs for user {session["user_id"]}: {e}')
            return jsonify({'theme': 'light', 'locale': 'en', 'notifications': True})
    return jsonify({'theme': 'light', 'locale': 'en', 'notifications': True})

@app.route('/api/preferences', methods=['PUT'])
@require_auth
def update_preferences():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    # Validate theme
    allowed_themes = ['light', 'dark', 'system']
    theme = data.get('theme', 'light')
    if theme not in allowed_themes:
        theme = 'light'

    prefs = UserPreferences(
        theme=theme,
        locale=data.get('locale', 'en')[:5],
        notifications=bool(data.get('notifications', True))
    )

    serialized = base64.b64encode(zlib.compress(pickle.dumps(prefs))).decode()
    db = get_db()
    db.execute('INSERT OR REPLACE INTO user_prefs (user_id, prefs_blob) VALUES (?, ?)',
               (session['user_id'], serialized))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/api/preferences/import', methods=['POST'])
@require_auth
def import_preferences():
    """Import preferences from exported blob (for account migration)"""
    data = request.get_json()
    blob = data.get('blob', '')

    if not blob or len(blob) > 10240:
        return jsonify({'error': 'invalid blob'}), 400

    # Verify the blob has valid base64 structure
    try:
        raw = base64.b64decode(blob)
    except Exception:
        return jsonify({'error': 'invalid encoding'}), 400

    # Store directly - will be deserialized on next GET
    db = get_db()
    db.execute('INSERT OR REPLACE INTO user_prefs (user_id, prefs_blob) VALUES (?, ?)',
               (session['user_id'], blob))
    db.commit()
    return jsonify({'status': 'imported'})

@app.route('/api/preferences/export', methods=['GET'])
@require_auth
def export_preferences():
    db = get_db()
    row = db.execute('SELECT prefs_blob FROM user_prefs WHERE user_id = ?',
                     (session['user_id'],)).fetchone()
    if row:
        return jsonify({'blob': row['prefs_blob']})
    return jsonify({'blob': None})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
